// Monthly research monitoring. Does not certify reserves or classify proved volumes.
const finite=v=>(typeof v==='number'||typeof v==='string')&&String(v).trim()!==''&&Number.isFinite(Number(v));
const avg=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:0;
export function monthIndex(s){if(typeof s!=='string'||!/^\d{4}-(0[1-9]|1[0-2])$/.test(s))throw Error('月份必须为YYYY-MM：'+s);return Number(s.slice(0,4))*12+Number(s.slice(5))-1;}
export function monthName(i){return Math.floor(i/12)+'-'+String(i%12+1).padStart(2,'0');}
export function monthDays(s){const i=monthIndex(s);return new Date(Date.UTC(Math.floor(i/12),i%12+1,0)).getUTCDate();}
const has=v=>v!==null&&v!==undefined&&String(v).trim()!=='';
export function validateMonthly(rows){if(!Array.isArray(rows)||!rows.length)throw Error('需要非空月度数据');const seen=new Set();return rows.map(r=>{monthIndex(r.month);if(seen.has(r.month))throw Error('月度数据重复：'+r.month+'；请先汇总为每月一行');seen.add(r.month);const out={...r};for(const k of ['oil_tonnes','active_wells']){if(!finite(r[k])||Number(r[k])<0)throw Error(k+'必须为非负数：'+r.month);out[k]=Number(r[k]);}if(out.oil_tonnes>0&&out.active_wells===0)throw Error('正产油量对应的在产井数不能为0：'+r.month);for(const k of ['water_m3','pressure_mpa','injection_m3','density_t_per_m3'])if(has(r[k])){if(!finite(r[k])||Number(r[k])<0||k==='density_t_per_m3'&&Number(r[k])===0)throw Error(k+'必须为有效非负数，密度需为正');out[k]=Number(r[k]);}else out[k]=null;return out;}).sort((a,b)=>a.month.localeCompare(b.month));}
