function rng(seed){let s=seed>>>0;return()=>((s=(Math.imul(s,1664525)+1013904223)>>>0)/4294967296);}
function gaussian(random){const a=Math.max(1e-15,random()),b=random();return Math.sqrt(-2*Math.log(a))*Math.cos(2*Math.PI*b);}
const q=(a,p)=>{const s=[...a].sort((a,b)=>a-b),v=(s.length-1)*p,i=Math.floor(v);return s[i]+(s[Math.min(i+1,s.length-1)]-s[i])*(v-i);};
