function publicFit(f){if(!f)return null;return {name:'Arps指数递减 / 对数线性OLS（按在产井与日历天归一化）',alpha:f.alpha,beta:f.beta,monthlyDecline:1-Math.exp(f.beta),annualDecline:f.annualDecline,sigmaLog:f.sigma,r2:f.r2,n:f.n,origin:monthName(f.origin),firstMonth:f.firstMonth,lastMonth:f.lastMonth};}
function externalPlan(rows,year,freezeDate){if(!Array.isArray(rows)||!rows.length)throw Error('原始年末计划不能为空');const seen=new Set();return rows.map(r=>{monthIndex(r.month);if(seen.has(r.month))throw Error('原始计划月份重复');seen.add(r.month);if(!/^\d{4}-\d{2}-\d{2}$/.test(r.issued_on??'')||!Number.isFinite(Date.parse(r.issued_on))||r.issued_on>freezeDate)throw Error('原始计划必须有不晚于冻结日的issued_on');if(monthIndex(r.month)<year*12)throw Error('原始计划月份必须晚于年末冻结月');if(!finite(r.forecast_oil_tonnes)||Number(r.forecast_oil_tonnes)<=0)throw Error('计划产油必须为正吨/月');const out={month:r.month,prediction:Number(r.forecast_oil_tonnes),ci_low:null,ci_high:null,pi_low:null,pi_high:null,actual:null};for(const prefix of ['ci','pi']){const l=r[prefix+'_low'],h=r[prefix+'_high'];if(has(l)||has(h)){if(!finite(l)||!finite(h)||Number(l)<0||Number(h)<Number(l))throw Error('原始计划区间上下限无效');out[prefix+'_low']=Number(l);out[prefix+'_high']=Number(h);}}return out;}).sort((a,b)=>a.month.localeCompare(b.month));}
