 if(![fitMonths,updateMonths,horizon,B,required].every(Number.isInteger)||fitMonths<12||fitMonths>60||updateMonths<6||updateMonths>24||horizon<1||horizon>36||B<200||B>1000||required<1||required>12||!Number.isFinite(warning)||warning<=0||severe<warning||severe>100||!Number.isFinite(gain)||gain<0||gain>.5)throw Error('参数范围：拟合12–60月，更新6–24个有效月，预测1–36月，Bootstrap200–1000次；预警阈值需正且严重阈值不小于关注阈值，条件增幅0–50%');
