 const latestPositive=observed.filter(r=>r.oil_tonnes>0&&r.active_wells>0).slice(-updateMonths),updated=bootstrapFit(fitDecline(latestPositive),B,seed+19),plannedWells=options.plannedWells===undefined||options.plannedWells===null?latest.active_wells:Number(options.plannedWells);if(!Number.isFinite(plannedWells)||plannedWells<0||baseWells!==null&&plannedWells>baseWells)throw Error('情景在产井数需非负且不超过年末已有在产井数；新增井需单列评价');
 const current=[],currentRows=new Map(observed.filter(r=>r.month>freezeMonth).map(r=>[r.month,r])),plan=new Map(baseline.map(r=>[r.month,r]));let streak=0,cusum=0;for(let i=(baseYear+1)*12;i<=monthIndex(asOf);i++){const month=monthName(i),actual=currentRows.get(month),p=plan.get(month);if(!actual||!p){streak=0;current.push({month,actual:actual?.oil_tonnes??null,prediction:p?.prediction??null,level:'灰',reason:!actual?'缺少本月观测':'原计划缺少本月预测',deviation:null,cusum,p_lower:null,p_adjusted:null});continue;}const deviation=100*(actual.oil_tonnes-p.prediction)/p.prediction;let z=null,pLower=null;if(frozen){const x=monthIndex(month)-frozen.origin,sd=Math.max(1e-8,frozen.sigma*Math.sqrt(1+1/frozen.n+(x-frozen.xmean)**2/frozen.sxx));z=actual.oil_tonnes===0?-8:(Math.log(actual.oil_tonnes/(monthDays(month)*baseWells))-frozen.alpha-frozen.beta*x)/sd;pLower=actual.oil_tonnes===0?0:normalCDF(z);}const pAdjusted=pLower===null?null:Math.min(1,12*pLower),below=p.pi_low!==null&&actual.oil_tonnes<p.pi_low,above=p.pi_high!==null&&actual.oil_tonnes>p.pi_high;streak=deviation<=-warning?streak+1:0;if(z!==null)cusum=Math.max(0,cusum-z-.5);let level='绿',reasons=[];if(deviation<=-severe){level='红';reasons.push('月产偏差达到严重阈值');}else if(streak>=required){level='红';reasons.push('连续偏低达到设定月数');}else if(deviation<=-warning||below){level='黄';reasons.push(deviation<=-warning?'月产偏差达到关注阈值':'低于95%单月预测下界');}if(cusum>5&&deviation<0){level='红';reasons.push('负向CUSUM持续偏移');}if(pAdjusted!==null&&pAdjusted<.05&&deviation<0){level='红';reasons.push('单侧尾概率经12月Bonferroni校正后仍偏低');}if(deviation>=warning||above){if(level==='绿')level='蓝';reasons.push('超出基准，需核查措施、计量与可持续性');}current.push({...p,actual:actual.oil_tonnes,deviation,level,reason:reasons.join('；')||'未触发当前规则',streak,cusum,p_lower:pLower,p_adjusted:pAdjusted});}
